// (i) transpose (1,2)
%x  : tensor<2x3x4xf32, strides=[12,4,1]>
%x1 : tensor<2x4x3xf32, strides=[12,1,4]>       // pure view: shape/stride swap

// (ii) reshape(6,4) on the contiguous [2,3,4]
%x  : tensor<2x3x4xf32, strides=[12,4,1]>
%x2 : tensor<6x4xf32,   strides=[4,1]>           // pure view: fold outer dims

// (iii) reshape(4,6) on the contiguous [2,3,4]
// Requires a re-index that a single (shape, stride) pair cannot express; needs copy
%x3 : tensor<4x6xf32> = materialize(reshape %x to [4,6])
